"""In-memory registry of loaded hook callables."""

from __future__ import annotations

from typing import Callable, NamedTuple

from rasa.mantle.hooks.constants import (
    HOOK_LANE_ATTR,
    HOOK_POINT_ATTR,
    HOOK_TIMEOUT_MS_ATTR,
)
from rasa.mantle.hooks.decorators import _is_hook_function
from rasa.mantle.hooks.exceptions import DuplicateModifierError
from rasa.mantle.hooks.types import OBSERVE_LANE, HookLane


class RegisteredHook(NamedTuple):
    """One loaded hook callable and its metadata."""

    func: Callable[..., object]
    point: str
    lane: HookLane
    timeout_ms: int
    module_path: str | None = None


class HookRegistry:
    """Ordered observer lists plus at most one modifier per point."""

    def __init__(self) -> None:
        self._observers: dict[str, list[RegisteredHook]] = {}
        self._modifiers: dict[str, RegisteredHook] = {}

    @classmethod
    def empty(cls) -> "HookRegistry":
        return cls()

    def register(self, hook: RegisteredHook) -> None:
        if hook.lane == OBSERVE_LANE:
            self._observers.setdefault(hook.point, []).append(hook)
            return

        if hook.point in self._modifiers:
            existing = self._modifiers[hook.point]
            raise DuplicateModifierError(
                f"Duplicate modify hook for point {hook.point!r}: "
                f"{existing.func.__name__!r} and {hook.func.__name__!r}."
            )
        self._modifiers[hook.point] = hook

    def register_function(
        self,
        func: Callable[..., object],
        *,
        module_path: str | None = None,
    ) -> None:
        if not _is_hook_function(func):
            return

        self.register(
            RegisteredHook(
                func=func,
                point=getattr(func, HOOK_POINT_ATTR),
                lane=getattr(func, HOOK_LANE_ATTR),
                timeout_ms=getattr(func, HOOK_TIMEOUT_MS_ATTR),
                module_path=module_path,
            )
        )

    def observers(self, point: str) -> list[RegisteredHook]:
        return list(self._observers.get(point, ()))

    def modifier(self, point: str) -> RegisteredHook | None:
        return self._modifiers.get(point)

    @property
    def observer_count(self) -> int:
        return sum(len(items) for items in self._observers.values())

    @property
    def modifier_count(self) -> int:
        return len(self._modifiers)

    def all_hooks(self) -> list[RegisteredHook]:
        hooks = [hook for hooks in self._observers.values() for hook in hooks]
        hooks.extend(self._modifiers.values())
        return hooks
